import pandas as pd
import numpy as np
import base64
import io
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import seaborn as sns

# Set style for professional look
sns.set_theme(style="whitegrid")
plt.rcParams['font.family'] = 'sans-serif'
plt.rcParams['font.sans-serif'] = ['Arial', 'Helvetica', 'DejaVu Sans']

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)

# Calculate basic stats
min_price = df['Crude_Oil_Price'].min()
max_price = df['Crude_Oil_Price'].max()
price_range = max_price - min_price
min_date = df.loc[df['Crude_Oil_Price'].idxmin(), 'Date'].strftime('%b %Y')
max_date = df.loc[df['Crude_Oil_Price'].idxmax(), 'Date'].strftime('%b %Y')

# CAGR
first_price = df['Crude_Oil_Price'].iloc[0]
last_price = df['Crude_Oil_Price'].iloc[-1]
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = ((last_price / first_price) ** (1 / years)) - 1

# Month-over-Month changes
df['MoM_Abs'] = df['Crude_Oil_Price'].diff()
df['MoM_Pct'] = df['Crude_Oil_Price'].pct_change()

max_abs_inc = df.loc[df['MoM_Abs'].idxmax()]
max_abs_dec = df.loc[df['MoM_Abs'].idxmin()]
max_pct_inc = df.loc[df['MoM_Pct'].idxmax()]
max_pct_dec = df.loc[df['MoM_Pct'].idxmin()]

# Decade analysis
df['Decade'] = (df['Date'].dt.year // 10 * 10).astype(str) + 's'
decade_stats = df.groupby('Decade')['Crude_Oil_Price'].agg(['mean', 'std', 'min', 'max']).reset_index()
highest_avg_decade = decade_stats.loc[decade_stats['mean'].idxmax()]

# Volatility
overall_std = df['Crude_Oil_Price'].std()

# Function to convert plot to base64
def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Chart 1: Long-Term Trend
fig1, ax1 = plt.subplots(figsize=(12, 6))
ax1.plot(df['Date'], df['Crude_Oil_Price'], color='#1f77b4', linewidth=2)
ax1.set_title('Global Crude Oil Prices (1970-2026)', fontsize=16, fontweight='bold', pad=15)
ax1.set_ylabel('Price (USD/bbl)', fontsize=12)
ax1.set_xlabel('Year', fontsize=12)
ax1.fill_between(df['Date'], df['Crude_Oil_Price'], alpha=0.2, color='#1f77b4')
# Annotate key events (approximate dates)
events = {
    '1973-10-01': '1973 Oil Crisis',
    '1979-01-01': '1979 Energy Crisis',
    '1990-08-01': 'Gulf War',
    '2008-07-01': '2008 Peak',
    '2014-11-01': '2014 Price Crash',
    '2020-04-01': 'COVID-19 Shock'
}
for date_str, label in events.items():
    event_date = pd.to_datetime(date_str)
    # Find closest date in df
    if event_date in df['Date'].values:
        idx = df.index[df['Date'] == event_date][0]
        price = df.loc[idx, 'Crude_Oil_Price']
        ax1.annotate(label, xy=(event_date, price), xytext=(0, 20),
                     textcoords='offset points', ha='center', va='bottom',
                     bbox=dict(boxstyle='round,pad=0.3', fc='yellow', alpha=0.5),
                     arrowprops=dict(arrowstyle='->', connectionstyle='arc3,rad=0'))
plt.tight_layout()
chart_long_term = fig_to_base64(fig1)
plt.close(fig1)

# Chart 2: Decade Boxplots
fig2, ax2 = plt.subplots(figsize=(10, 6))
sns.boxplot(x='Decade', y='Crude_Oil_Price', data=df, ax=ax2, palette='Blues_d')
ax2.set_title('Price Distribution by Decade', fontsize=16, fontweight='bold', pad=15)
ax2.set_ylabel('Price (USD/bbl)', fontsize=12)
ax2.set_xlabel('Decade', fontsize=12)
plt.tight_layout()
chart_decades = fig_to_base64(fig2)
plt.close(fig2)

# Chart 3: Volatility (Rolling 12-month STD)
df['Rolling_STD_12M'] = df['Crude_Oil_Price'].rolling(window=12).std()
fig3, ax3 = plt.subplots(figsize=(12, 5))
ax3.plot(df['Date'], df['Rolling_STD_12M'], color='#d62728', linewidth=1.5)
ax3.set_title('Price Volatility (Rolling 12-Month Standard Deviation)', fontsize=16, fontweight='bold', pad=15)
ax3.set_ylabel('Standard Deviation (USD)', fontsize=12)
ax3.set_xlabel('Year', fontsize=12)
ax3.fill_between(df['Date'], df['Rolling_STD_12M'], alpha=0.2, color='#d62728')
plt.tight_layout()
chart_volatility = fig_to_base64(fig3)
plt.close(fig3)

# Chart 4: MoM Percentage Changes
fig4, ax4 = plt.subplots(figsize=(12, 5))
ax4.bar(df['Date'], df['MoM_Pct'] * 100, color=np.where(df['MoM_Pct'] > 0, 'g', 'r'), width=20)
ax4.set_title('Month-over-Month Percentage Change (%)', fontsize=16, fontweight='bold', pad=15)
ax4.set_ylabel('Change (%)', fontsize=12)
ax4.set_xlabel('Year', fontsize=12)
plt.tight_layout()
chart_mom = fig_to_base64(fig4)
plt.close(fig4)

